CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL COLLATE NOCASE UNIQUE, password TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('Admin','Staff','Adopter')), phone TEXT NOT NULL DEFAULT '', address TEXT NOT NULL DEFAULT '', created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS pets(id INTEGER PRIMARY KEY, name TEXT NOT NULL, species TEXT NOT NULL, breed TEXT NOT NULL, age TEXT NOT NULL, gender TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'Available' CHECK(status IN ('Available','In foster','Adopted','On hold')), description TEXT NOT NULL DEFAULT '', photo TEXT, intake_date TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS applications(id INTEGER PRIMARY KEY, pet_id INTEGER NOT NULL REFERENCES pets(id), user_id INTEGER NOT NULL REFERENCES users(id), housing TEXT NOT NULL, experience TEXT NOT NULL, reason TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'Pending' CHECK(status IN ('Pending','Approved','Rejected')), notes TEXT NOT NULL DEFAULT '', created_at TEXT DEFAULT CURRENT_TIMESTAMP, updated_at TEXT DEFAULT CURRENT_TIMESTAMP, UNIQUE(pet_id,user_id));
CREATE TABLE IF NOT EXISTS medical(id INTEGER PRIMARY KEY, pet_id INTEGER NOT NULL REFERENCES pets(id), kind TEXT NOT NULL, record_date TEXT NOT NULL, details TEXT NOT NULL, next_due TEXT, created_by INTEGER REFERENCES users(id));
CREATE TABLE IF NOT EXISTS contacts(id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id), note TEXT NOT NULL, created_by INTEGER REFERENCES users(id), created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS contracts(id INTEGER PRIMARY KEY, application_id INTEGER NOT NULL UNIQUE REFERENCES applications(id), fee REAL NOT NULL CHECK(fee>=0), payment TEXT NOT NULL CHECK(payment IN ('Unpaid','Paid','Waived')), agreement TEXT NOT NULL, ownership_document TEXT NOT NULL, signed_date TEXT NOT NULL, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS fosters(id INTEGER PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL, phone TEXT NOT NULL, address TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS placements(id INTEGER PRIMARY KEY, pet_id INTEGER NOT NULL REFERENCES pets(id), foster_id INTEGER NOT NULL REFERENCES fosters(id), start_date TEXT NOT NULL, end_date TEXT);
CREATE UNIQUE INDEX IF NOT EXISTS one_active_foster ON placements(pet_id) WHERE end_date IS NULL;
CREATE TABLE IF NOT EXISTS notifications(id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id), message TEXT NOT NULL, seen INTEGER NOT NULL DEFAULT 0, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS audit(id INTEGER PRIMARY KEY, user_id INTEGER REFERENCES users(id), action TEXT NOT NULL, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS login_attempts(id INTEGER PRIMARY KEY, email TEXT NOT NULL, ip TEXT NOT NULL, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
